struct TopLevel * cJSON_ParseTopLevel(const char * s) {
    struct TopLevel * x = NULL;
    if (NULL != s) {
        cJSON * j = cJSON_Parse(s);
        if (NULL != j) {
            x = cJSON_GetTopLevelValue(j);
            cJSON_Delete(j);
        }
    }
    return x;
}

struct TopLevel * cJSON_GetTopLevelValue(const cJSON * j) {
    struct TopLevel * x = NULL;
    if (NULL != j) {
        if (NULL != (x = cJSON_malloc(sizeof(struct TopLevel)))) {
            memset(x, 0, sizeof(struct TopLevel));
            if (cJSON_HasObjectItem(j, "enum")) {
                if (!cJSON_IsString(cJSON_GetObjectItemCaseSensitive(j, "enum"))) { cJSON_DeleteTopLevel(x); return NULL; }
                if (!cJSON_IsString(cJSON_GetObjectItemCaseSensitive(j, "enum")) || 0 == cJSON_GetEnumValue(cJSON_GetObjectItemCaseSensitive(j, "enum"))) { cJSON_DeleteTopLevel(x); return NULL; }
                if (NULL != (x->top_level_enum = cJSON_malloc(sizeof(enum Enum)))) {
                    *x->top_level_enum = cJSON_GetEnumValue(cJSON_GetObjectItemCaseSensitive(j, "enum"));
                }
            }
        }
    }
    return x;
}

cJSON * cJSON_CreateTopLevel(const struct TopLevel * x) {
    cJSON * j = NULL;
    if (NULL != x) {
        if (NULL != (j = cJSON_CreateObject())) {
            if (NULL != x->top_level_enum) {
                cJSON_AddItemToObject(j, "enum", cJSON_CreateEnum(*x->top_level_enum));
            }
        }
    }
    return j;
}

char * cJSON_PrintTopLevel(const struct TopLevel * x) {
    char * s = NULL;
    if (NULL != x) {
        cJSON * j = cJSON_CreateTopLevel(x);
        if (NULL != j) {
            s = cJSON_Print(j);
            cJSON_Delete(j);
        }
    }
    return s;
}

void cJSON_DeleteTopLevel(struct TopLevel * x) {
    if (NULL != x) {
        if (NULL != x->top_level_enum) {
            cJSON_free(x->top_level_enum);
        }
        cJSON_free(x);
    }
}
